// Generates a downloadable PDF of the full (filtered) employee list,
// with the tenant choosing which columns appear. Branded with the
// TENANT's own company name in the header (matches the single-employee
// report), with a small "Generated by Lexora" platform attribution in
// the footer alongside page numbers.

import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import type { Employee, HrTeam, HrLocation } from "./hr-api";

const fmtDate = (d?: string | null) =>
  d
    ? new Date(d).toLocaleDateString("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      })
    : "—";

const teamName = (e: Employee) =>
  typeof e.teamId === "object" && e.teamId !== null
    ? (e.teamId as HrTeam).name
    : "—";

const locName = (e: Employee) =>
  typeof e.locationId === "object" && e.locationId !== null
    ? (e.locationId as HrLocation).name
    : "—";

const titleCase = (s?: string | null) =>
  s ? s.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()) : "—";

export interface EmployeeListColumn {
  id: string;
  label: string;
  get: (e: Employee) => string;
}

// The full set of columns a tenant can choose from. Order here is the
// order they appear in the table when selected.
export const EMPLOYEE_LIST_COLUMNS: EmployeeListColumn[] = [
  {
    id: "name",
    label: "Name",
    get: (e) => `${e.firstName} ${e.lastName}`,
  },
  {
    id: "employeeNumber",
    label: "Employee No.",
    get: (e) => e.employeeNumber ?? e._id,
  },
  { id: "email", label: "Email", get: (e) => e.email },
  { id: "phone", label: "Phone", get: (e) => e.phone ?? "—" },
  { id: "gender", label: "Gender", get: (e) => titleCase(e.gender) },
  { id: "jobTitle", label: "Job Title", get: (e) => e.jobTitle ?? "—" },
  { id: "team", label: "Team", get: teamName },
  { id: "location", label: "Location", get: locName },
  {
    id: "employmentType",
    label: "Employment Type",
    get: (e) => titleCase(e.employmentType),
  },
  {
    id: "employmentStatus",
    label: "Status",
    get: (e) => titleCase(e.employmentStatus ?? "active"),
  },
  {
    id: "hierarchyRole",
    label: "Hierarchy Role",
    get: (e) => titleCase(e.hierarchyRole),
  },
  { id: "roleLevel", label: "Role Level", get: (e) => titleCase(e.roleLevel) },
  { id: "startDate", label: "Start Date", get: (e) => fmtDate(e.startDate) },
  {
    id: "salary",
    label: "Salary",
    get: (e) =>
      e.salary != null
        ? `${e.salary.toLocaleString()} ${e.salaryCurrency ?? ""}`.trim()
        : "—",
  },
  {
    id: "nationality",
    label: "Nationality",
    get: (e) => e.nationality ?? "—",
  },
  {
    id: "dateOfBirth",
    label: "Date of Birth",
    get: (e) => fmtDate(e.dateOfBirth),
  },
  { id: "taxId", label: "Tax ID", get: (e) => e.taxId ?? "—" },
  {
    id: "workerCategory",
    label: "Worker Category",
    get: (e) => titleCase(e.workerCategory),
  },
];

// A sensible starting selection — the tenant can add/remove from the
// full column list above before downloading.
export const DEFAULT_EMPLOYEE_LIST_COLUMN_IDS = [
  "name",
  "employeeNumber",
  "email",
  "jobTitle",
  "team",
  "location",
  "employmentStatus",
];

const HEADER_FILL: [number, number, number] = [67, 56, 202]; // indigo-700
const ROW_HEAD_FILL: [number, number, number] = [99, 102, 241]; // indigo-500

export function downloadEmployeeListReport(
  employees: Employee[],
  columnIds: string[],
  tenantName: string,
) {
  const columns = EMPLOYEE_LIST_COLUMNS.filter((c) => columnIds.includes(c.id));
  if (columns.length === 0) return;

  const generatedAt = new Date().toLocaleString("en-GB");

  const doc = new jsPDF({
    orientation: "landscape",
    unit: "pt",
    format: "a4",
  });
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 32;

  // ── Header bar ──
  doc.setFillColor(...HEADER_FILL);
  doc.rect(0, 0, pageWidth, 70, "F");
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(10);
  doc.setFont("helvetica", "bold");
  doc.text(tenantName.toUpperCase(), margin, 24);
  doc.setFontSize(16);
  doc.text("Employee List Report", margin, 44);
  doc.setFontSize(9);
  doc.setFont("helvetica", "normal");
  doc.text(
    `Generated ${generatedAt} · ${employees.length} employee${employees.length !== 1 ? "s" : ""} · Confidential, for internal HR use only`,
    margin,
    58,
  );

  autoTable(doc, {
    startY: 90,
    head: [columns.map((c) => c.label)],
    body: employees.length
      ? employees.map((e) => columns.map((c) => c.get(e)))
      : [columns.map(() => "—")],
    theme: "grid",
    styles: { fontSize: 8, cellPadding: 5, overflow: "linebreak" },
    headStyles: { fillColor: ROW_HEAD_FILL, textColor: 255, fontSize: 8.5 },
    margin: { left: margin, right: margin },
    didDrawPage: () => {
      // Repeat a slim continuation header on pages after the first so a
      // printed/scrolled page is never missing context.
    },
  });

  // Footer — platform attribution + page numbers
  const totalPages = doc.getNumberOfPages();
  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(140);
    doc.setFont("helvetica", "normal");
    doc.text("Generated by Lexora", margin, pageHeight - 20);
    doc.text(
      `Page ${i} of ${totalPages}`,
      pageWidth - margin,
      pageHeight - 20,
      {
        align: "right",
      },
    );
  }

  doc.save(`employee-list-report-${new Date().toISOString().slice(0, 10)}.pdf`);
}
